   nodes.forEach(node=>{if(!originalText.has(node))originalText.set(node,node.nodeValue);const raw=originalText.get(node);const trimmed=raw.trim();if(!trimmed)return;const translated=T[trimmed]?.[index];if(translated!==undefined){node.nodeValue=raw.replace(trimmed,translated)}else{node.nodeValue=raw}});
