   document.querySelectorAll('[aria-label]').forEach(el=>{const store=originalAttributes.ariaLabel;if(!store.has(el))store.set(el,el.getAttribute('aria-label'));const val=store.get(el);if(T[val])el.setAttribute('aria-label',T[val][index]);else el.setAttribute('aria-label',val)});
   document.querySelectorAll('[title]').forEach(el=>{const store=originalAttributes.title;if(!store.has(el))store.set(el,el.getAttribute('title'));const val=store.get(el);if(T[val])el.setAttribute('title',T[val][index]);else el.setAttribute('title',val)});
   const titles={'home':['Jorsid Beauty by Kessy — Friseur & Beauty','Jorsid Beauty by Kessy — Coiffure & beauté','Jorsid Beauty by Kessy — Hair & Beauty'],'services':['Leistungen | Jorsid Beauty by Kessy','Prestations | Jorsid Beauty by Kessy','Services | Jorsid Beauty by Kessy'],'about':['Über Jorsid Beauty by Kessy','À propos — Jorsid Beauty by Kessy','About — Jorsid Beauty by Kessy'],'contact':['Kontakt — Jorsid Beauty by Kessy','Contact — Jorsid Beauty by Kessy','Contact — Jorsid Beauty by Kessy'],'booking':['Termin buchen | Jorsid Beauty by Kessy','Réserver | Jorsid Beauty by Kessy','Book | Jorsid Beauty by Kessy'],'confirmation':['Anfrage erhalten | Jorsid Beauty by Kessy','Demande reçue | Jorsid Beauty by Kessy','Request received | Jorsid Beauty by Kessy']};
   const path=location.pathname;const key=path==='/prestations'?'services':path==='/a-propos'?'about':path==='/contact'?'contact':path==='/reservation'?'booking':path.includes('/reservation/confirmation')?'confirmation':'home';document.title=titles[key][index];
   try{localStorage.setItem('jorsid-language',lang)}catch(e){}
   if(toggle){const opened=toggle.getAttribute('aria-expanded')==='true';const labels={de:opened?'Menü schließen':'Menü öffnen',fr:opened?'Fermer le menu':'Ouvrir le menu',en:opened?'Close menu':'Open menu'};toggle.setAttribute('aria-label',labels[lang])}
   document.dispatchEvent(new CustomEvent('jorsid:language-changed',{detail:{language:lang}}));
 }
 if(select){select.addEventListener('change',()=>applyLanguage(select.value));}
