 // Richer, staggered reveal and micro-interactions across every page.
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduce&&'IntersectionObserver'in window){
  const targets=document.querySelectorAll('main section, .section,.pagehero,.cards article,.booking-form,.booking-aside,.cta,.confirmation-card,.contact > div,.service-card');
  targets.forEach((el,i)=>{el.classList.add('v2-reveal');el.style.setProperty('--reveal-delay',`${Math.min(i%5,4)*75}ms`)});
  const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('v2-visible');observer.unobserve(entry.target)}}),{threshold:.06,rootMargin:'0px 0px -30px 0px'});targets.forEach(el=>observer.observe(el));
 }
 document.querySelectorAll('.btn,.text-link,.service-card,.cards article').forEach(el=>el.classList.add('v2-interactive'));
